import * as S from './states.js?v=109';
import * as P from './pregame.js?v=102';
import * as V from './saves.js?v=109';
export const names={symbioMate:'SymbioMate 共生防护',symbioBomb:'SymbioBomb 共生炸弹'};
export function candidates(state,owner,key){return state.units.filter(u=>u.team===owner.team&&u.id!==owner.id&&Number(u.transmutation?.threshold)>0&&S.onTable(u)&&!(u.states||[]).some(s=>['camouflaged','impersonation','impersonation1','impersonation2','holoecho'].includes(s))&&!u[key]);}
export function assign(state,owner,key,targetId){if(!Object.hasOwn(names,key)||state.phase!=='deploy'||!P.editable(state,owner)||!(owner[key+'Stock']>0))return {error:'只能在拥有者的部署阶段分配未使用装备'};const target=candidates(state,owner,key).find(u=>u.id===targetId);if(!target)return {error:'必须选择场上的同军表Transmutation(X)模型；每类装备最多一件'};target[key]={ownerId:owner.id};owner[key+'Stock']--;return {target};}
export function html(state,u){if(state.phase!=='deploy'||!P.editable(state,u))return '';return Object.keys(names).filter(k=>u[k+'Stock']>0).map(k=>`<fieldset><legend>${names[k]} · 剩余${u[k+'Stock']}</legend><select data-symbio-target="${k}">${candidates(state,u,k).map(v=>`<option value="${v.id}">${v.name}</option>`).join('')}</select><button data-symbio-assign="${k}" ${candidates(state,u,k).length?'':'disabled'}>分配给场上模型</button><p>仅部署拥有者时分配；需要Transmutation(X)，且不能处于标记／桌外／隐匿部署。</p></fieldset>`).join('');}
export function bind(root,state,u,{render,toast,log}){for(const el of root.querySelectorAll('[data-symbio-assign]'))el.onclick=()=>{const key=el.dataset.symbioAssign,r=assign(state,u,key,root.querySelector('[data-symbio-target="'+key+'"]').value);if(r.error)toast(r.error);else log(u.name+' 将 '+names[key]+' 分配给 '+r.target.name);render();};}
// All hits in the order use the equipment once a saving roll activates it.
export function prepareMate(result,units){const plans=V.allPlans(result),ids=new Set(plans.filter(p=>p.initialCount&&units.find(u=>u.id===p.targetId)?.symbioMate).map(p=>p.targetId));for(const id of ids){units.find(u=>u.id===id).symbioMateUsed=true;for(const p of plans.filter(p=>p.targetId===id&&p.noSavingRoll&&!p.comms)){p.effects=[];p.symbioMateBlocked=true;}}return ids;}
export function conclude(units){const messages=[];for(const u of units){if(u.symbioMateUsed){delete u.symbioMate;delete u.symbioMateUsed;messages.push(u.name+'：SymbioMate已在本命令使用并移除。');}if(u.symbioBombUsed){delete u.symbioBomb;delete u.symbioBombUsed;messages.push(u.name+'：SymbioBomb已使用并移除。');}}return messages;}
